#!/usr/bin/env node
/**
 * Tests for scripts/gate.mjs --red called twice: the second proof adds to the stored one.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'scripts', 'gate.mjs');
const created = [];

process.on('exit', () => {
  for (const dir of created) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp, let the OS have it */ }
  }
});

const git = (root, ...args) => spawnSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', ...args], { cwd: root, encoding: 'utf8' }).stdout.trim();
const { NODE_TEST_CONTEXT, ...env } = process.env;
const gate = (root, ...args) => spawnSync(process.execPath, [SCRIPT, '--root', root, ...args], { encoding: 'utf8', env });
const FAILING = "import { test } from 'node:test';\nimport assert from 'node:assert/strict';\ntest('fails', () => assert.fail('red'));\n";

/** A temp git repository with an active perimeter and two failing test files, a.test.mjs and b.test.mjs. */
function repoWithTwoTests() {
  const root = mkdtempSync(join(tmpdir(), 'gate-red-'));
  created.push(root);
  git(root, 'init');
  writeFileSync(join(root, 'README.md'), 'hello\n');
  git(root, 'add', '-A');
  git(root, 'commit', '-m', 'init');
  const dir = join(root, '.git', 'deliver');
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, 'perimeter.md'), `branch: ${git(root, 'rev-parse', '--abbrev-ref', 'HEAD')}\nstatus: active\n- **\n`);
  writeFileSync(join(root, 'a.test.mjs'), FAILING);
  writeFileSync(join(root, 'b.test.mjs'), FAILING);
  return root;
}

const red = (root, file) => gate(root, '--red', '--unit', `node --test ${file}`, '--test-files', file);

test('given a stored proof for file a.test.mjs, when --red runs again with --test-files b.test.mjs, then the proof holds both a and b', () => {
  // Given
  const root = repoWithTwoTests();
  red(root, 'a.test.mjs');

  // When
  const res = red(root, 'b.test.mjs');

  // Then
  assert.ok(res.stdout.includes('red-proven'), res.stdout);
  const proof = JSON.parse(readFileSync(join(root, '.git', 'deliver', 'gate.json'), 'utf8')).proof;
  assert.deepEqual(Object.keys(proof.files).sort(), ['a.test.mjs', 'b.test.mjs']);
});
